namespace ghidra.program.model.data;



using org.junit;

using generic.test;

public class DataTypeNameComparatorTest : AbstractGTest {

	/* @Test */
	public void testDataTypeNameSort() {

		string[] names = new string[] {
			//@formatter:off
			"int",
			"INT",
			"int *",
			"INT *",
			"int [2]",
			"int * *",
			"INT_PTR",
			"s1 *",
			"S1 *",
			"S1.conflict",
			"s1",
			"S1",
			"S1.conflict1",
			"S1.conflict10",
			"S1.conflict2",
			"s1.conflict *",
			"s1.conflict2 *",
			"s1.conflict10"
			//@formatter:on
		};

		string[] sortedNames = new string[] {
			//@formatter:off
			"INT",
			"INT *",
			"int",
			"int *",
			"int * *",
			"int [2]",
			"INT_PTR",
			"S1",
			"S1 *",
			"S1.conflict",
			"S1.conflict1",
			"S1.conflict2",
			"S1.conflict10",
			"s1",
			"s1 *",
			"s1.conflict *",
			"s1.conflict2 *",
			"s1.conflict10"
			//@formatter:on
		};

		Arrays.sort(names, DataTypeNameComparator.INSTANCE);

		assertArraysEqualOrdered("Incorrect datatype name sort order", sortedNames, names);
	}

}
